const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'<path d="m3 11 9-8 9 8M5 10v11h5v-7h4v7h5V10"/>',pause:'<path d="M8 5v14M16 5v14"/>',play:'<path d="m8 4 12 8-12 8z"/>',reset:'<path d="M4 10a9 9 0 1 1 1 8M4 4v6h6"/>',sound:'<path d="M3 9h5l5-5v16l-5-5H3zM17 8q5 4 0 8M20 5q8 7 0 14"/>',mute:'<path d="M3 9h5l5-5v16l-5-5H3zM17 9l5 6m0-6-5 6"/>',arrow:'<path d="M3 12h18m-7-7 7 7-7 7"/>',check:'<path d="m4 12 6 6L21 4"/>',cross:'<path d="m6 6 12 12M18 6 6 18"/>',hand:'<path d="M9 13V4a2 2 0 0 1 4 0v7-3a2 2 0 0 1 4 0v4-2a2 2 0 0 1 4 0v6q0 6-6 6h-3q-3 0-5-3l-4-6q-1-3 2-2z"/>',fish:'<path d="m4 12-3-5v10zM4 12c5-10 13-10 19 0-6 10-14 10-19 0z"/><circle cx="16" cy="10" r="1"/>',star:'<path d="m12 2 3 7 8 1-6 5 2 8-7-4-7 4 2-8-6-5 8-1z"/>',book:'<path d="M12 5q-5-3-10-1v15q5-2 10 1 5-3 10-1V4q-5-2-10 1v15"/>',back:'<path d="M21 12H3m7-7-7 7 7 7"/>',coin:'<circle cx="12" cy="12" r="10"/><path d="M12 5v14m4-11c-8-5-12 4-4 4s4 10-4 4"/>'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.fish}</svg>`;}
function textSentence(text){return [...text].map(c=>c==='，'||c==='。'?`<span class="punct">${c}</span>`:c==='一'||c==='就'?`<span class="connector ${c==='一'?'first-connector':'then-connector'}">${c}</span>`:esc(c)).join('');}
function islandSentence(text){return textSentence(text).replace('<span class="punct">，</span>','<span class="punct">，</span><br>');}
function vocabPicture(id,cls=''){
 const w=WORDS[id];if(!w)return '';
 let x,y,width,height,src,fullWidth,fullHeight;
 if(w.atlas==='traffic'){x=w.id==='traffic'?0:887;y=0;width=height=887;src='fish-traffic-v4.png';fullWidth=1774;fullHeight=887;}
 else if(w.atlas==='fish'){const cell=1254/4;x=w.tile%4*cell;y=Math.floor(w.tile/4)*cell;width=height=cell;src='fish-words-v3.png';fullWidth=fullHeight=1254;}
 else{const columns=[[0,295],[301,589],[595,885],[891,1178],[1184,1475],[1480,1774]],rows=[[0,294],[300,575],[581,887]],[x0,x1]=columns[w.tile%6],[y0,y1]=rows[Math.floor(w.tile/6)];x=x0;y=y0;width=x1-x0;height=y1-y0;src='vocab-v2.png';fullWidth=1774;fullHeight=887;}
 const clip='vocab-clip-'+(++pictureSerial);
 return `<svg class="vocab-picture ${cls}" viewBox="${x} ${y} ${width} ${height}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${esc(w.text)}的圖畫"><defs><clipPath id="${clip}"><rect x="${x}" y="${y}" width="${width}" height="${height}"/></clipPath></defs><image clip-path="url(#${clip})" href="assets/${src}" x="0" y="0" width="${fullWidth}" height="${fullHeight}"/></svg>`;
}
function islandWordPicture(tile,label='生活動作圖畫'){const extraMap={1:0,2:1,3:2,11:3,12:4,13:5},extra=Object.hasOwn(extraMap,tile),n=extra?extraMap[tile]:tile,cols=extra?3:5,rows=extra?2:4;return `<span class="island-word-picture ${extra?'extra-island-word':''}" role="img" aria-label="${esc(label)}" style="--x:${n%cols*100/(cols-1)}%;--y:${Math.floor(n/cols)*100/(rows-1)}%"></span>`;}
function wordChoice(id,attrs='',cls=''){const w=WORDS[id];return `<button class="word-choice ${cls}" ${attrs} aria-label="${esc(w.text)}">${vocabPicture(id)}<strong>${w.text}</strong><small class="jp">${w.jp}</small>${cls==='wrong-card'||cls==='weak-card'?`<span class="wrong-badge">${icon('cross')}再試一試！</span>`:cls==='correct-card'?`<span class="choice-status status-correct">${icon('check')}</span>`:''}</button>`;}
function sprite(name,frame=0,row=0,cls=''){return `<span class="sprite ${name}-sprite ${cls}" role="img" aria-label="${name==='customer'?'小客人':'小漁夫'}" style="--frame:${frame*100/3}%;--row:${row*100}%"></span>`;}
function clearAudio(){audioTicket++;audioPending=false;speaker.onended=null;speaker.onerror=null;speaker.pause();document.querySelectorAll('.is-reading').forEach(b=>b.classList.remove('is-reading'));}
function audio(id,after){if(muted){if(after)after();return;}clearAudio();const ticket=audioTicket;let finished=false;audioPending=true;speaker.src=`assets/audio/${id}.mp3?v=20261027v17`;const end=()=>{if(finished||ticket!==audioTicket)return;finished=true;audioPending=false;document.querySelectorAll('.is-reading').forEach(b=>b.classList.remove('is-reading'));if(after)after();};speaker.onended=end;speaker.onerror=end;const review=document.querySelector(`[data-review="${id}"]`);if(review)review.classList.add('is-reading');speaker.play().catch(end);}
function sayWord(id,after){audio('v2-word-'+id,after);}
function announce(s){live.textContent=s;}
function later(delay,fn){const current=game;if(current)current.queue.after(delay,()=>{if(game===current)fn();});}
function dispose(){cancelTrainDrags();if(game){game.queue.clear();game=null;}clearAudio();app.className='';}
function summaryButton(type){return `<button class="control summary-control" data-action="summary" data-type="${type}" aria-label="全部題目總結">${icon('book')}<span>題目總結</span></button>`;}
function levelNavigation(type){const count=roundCount(type),g=game?.type===type?game:null;return `<nav class="level-navigation" aria-label="題目編號">${Array.from({length:count},(_,i)=>{const done=type==='sushi'?g?.paid.has(SUSHI[i].id):type==='fishing'?g?.players.every(p=>p.done.has(FIRSTS[i])):g?.stars.has(i),current=g&&g.phase!=='finished'&&(type==='fishing'?g.players.every(p=>p.first===FIRSTS[i]):g.round===i);return `<button class="level-dot ${type==='train'?(i<3?'tier-simple':'tier-advanced'):''} ${done?'done':''} ${current?'current':''}" data-jump-level="${i}" data-jump-game="${type}" aria-label="跳到第 ${i+1} 題" ${current?'aria-current="step"':''}>${i+1}</button>`;}).join('')}</nav>`;}
function toolbar({playing=false,extra=''}={}){return `<div class="toolbar">${extra}<button class="control" data-action="home" aria-label="返回主頁">${icon('home')}<span>主頁</span></button>${playing?`${game.phase!=='finished'?summaryButton(game.type):''}<button class="control pause-control" data-action="pause" aria-pressed="${game.paused}" aria-label="${game.paused?'繼續遊戲':'暫停遊戲'}">${icon(game.paused?'play':'pause')}<span>${game.paused?'繼續':'暫停'}</span></button><button class="control" data-action="restart" aria-label="重新開始遊戲">${icon('reset')}<span>重新開始</span></button>`:''}</div>`;}
function header(title,{playing=false,extra='',levelType=null}={}){return `<header class="header ${levelType?'header-with-levels':''}">${title?`<h1><span>${title}</span></h1>`:''}${toolbar({playing,extra})}${levelType?`<div class="header-levels">${levelNavigation(levelType)}</div>`:''}</header>`;}
function jumpToLevel(index,type=game?.type){if(!TITLES[type])return;const previous=game?.type===type?game:newGame(type),next=jumpRound(previous,index);if(!next)return;cancelTrainDrags();clearAudio();game=next;view=type;app.className='playing';lastFrame=performance.now();history.replaceState(null,'','#'+type);document.title=TITLES[type]+'｜中文句式小遊戲';announce('');if(type==='sushi')renderSushi();else if(type==='fishing')renderFishing();else if(type==='train')renderTrain();else{renderIsland();readIslandQuestion();}}
function pause(){if(!game)return;cancelTrainDrags();game.paused=!game.paused;game.queue.paused=game.paused;app.classList.toggle('is-paused',game.paused);if(game.paused)speaker.pause();else if(audioPending&&!muted)speaker.play().catch(()=>{});const b=$('.pause-control');b.innerHTML=icon(game.paused?'play':'pause')+`<span>${game.paused?'繼續':'暫停'}</span>`;b.setAttribute('aria-pressed',String(game.paused));b.setAttribute('aria-label',game.paused?'繼續遊戲':'暫停遊戲');const area=$('.play-area');if(area)area.querySelectorAll('button:not([data-jump-level])').forEach(b=>b.inert=game.paused);lastFrame=performance.now();}
function home(){dispose();view='home';history.replaceState(null,'','#home');document.title='中文句式小遊戲';announce('');app.innerHTML=`<main class="home-page">${header('')}<div class="home-title"><h2>一<span>……</span>就<span>……</span></h2></div><section class="game-menu"><article class="game-door blue-door"><h3>壽司小店</h3><p>二人合作</p><div class="menu-art sushi-cover"><img src="assets/sushi.png" alt="壽司餐廳">${sprite('customer',0,0)}</div><button class="primary blue" data-action="intro-sushi">開始營業${icon('arrow')}</button></article><article class="game-door amber-door"><h3>釣魚對戰</h3><p>左右對戰</p><div class="menu-art fishing-cover"><img src="assets/fishing.png" alt="小漁夫和海底世界"><img class="menu-swim" src="assets/fish-gold-v2.png" alt="可愛小魚"></div><button class="primary amber" data-action="intro-fishing">開始釣魚${icon('arrow')}</button></article><article class="game-door mint-door"><h3>小島生活任務</h3><p>家庭・校園・活動</p><div class="menu-art island-cover">${paintedScene('lamp')}</div><button class="primary mint" data-action="intro-island">開始探索${icon('arrow')}</button></article><article class="game-door train-door"><h3>小島句子列車</h3><p>拖卡合作</p><div class="menu-art"><img src="assets/train-station-v1.png" alt="小島蒸氣火車"></div><button class="primary train-primary" data-action="intro-train">開始組句${icon('arrow')}</button></article></section><p class="home-foot">${icon('hand')} 點選圖卡，一起完成句子。</p></main>`;}
function intro(type){if(type==='train'){introTrain();return;}dispose();view='intro-'+type;history.replaceState(null,'','#'+view);document.title=TITLES[type]+'｜中文句式小遊戲';const visual=type==='sushi'?`<div class="intro-large sushi-cover"><img src="assets/sushi.png" alt="壽司小店">${sprite('customer',0,0)}</div>`:type==='fishing'?`<div class="intro-large"><img src="assets/fishing.png" alt="卡通漁夫釣魚"></div>`:`<div class="intro-large">${paintedScene('lamp')}</div>`;const instructions=type==='sushi'?`<div class="visual-steps"><div>${vocabPicture('thirsty')}<b>看圖</b></div><span>→</span><div>${vocabPicture('water')}<b>選詞</b></div><span>→</span><div class="step-paid">${icon('coin')}<b>收款</b></div></div><p>看圖，選出圖中的動作。</p><p class="example">${textSentence('我一口渴，就喝水。')}</p>`:type==='fishing'?`<div class="sentence-guide"><div class="guide-item">${vocabPicture('closeEyes')}<span class="guide-arrow" aria-hidden="true">↑</span><p>${textSentence('我一閉上眼睛，')}</p></div><div class="guide-item">${vocabPicture('cannotSee')}<span class="guide-arrow amber-arrow" aria-hidden="true">↑</span><p>${textSentence('就看不見東西。')}</p></div></div><div class="reward-demo"><img src="assets/fish-gold-v2.png" alt="小魚"><span>答對一句</span><img src="assets/fish-blue-v2.png" alt="大魚"><span>連對五句</span></div>`:`<div class="visual-steps"><div>${islandWordPicture(10,'燈亮起來了')}<b>先選結果</b></div><span>→</span><div class="action-demo">${icon('hand')}<b>再做動作</b></div></div><p class="example">${textSentence('我一按開關，燈就亮起來了。')}</p><p>一人選圖，一人操作。</p>`;app.innerHTML=`<main class="intro-page">${header(TITLES[type],{extra:summaryButton(type),levelType:type})}<section class="intro-layout">${visual}<div class="intro-copy">${type==='fishing'?'':`<h2>${type==='sushi'?'合作完成訂單':'看一看，馬上發生甚麼？'}</h2>`}${instructions}<button class="primary ${type==='sushi'?'blue':type==='fishing'?'amber':'mint'}" data-action="start-${type}">${icon('play')}${type==='sushi'?'開始營業':type==='fishing'?'開始比賽':'開始任務'}</button></div></section></main>`;}
function trainDifficulty(simple,stage){return `<div class="train-difficulty ${simple?'difficulty-simple':'difficulty-advanced'}"><span class="difficulty-stars" aria-hidden="true">${icon('star')}${simple?'':icon('star')}</span><strong>${simple?'初階':'高階'}</strong><b>${stage}</b></div>`;}
function introTrain(){dispose();view='intro-train';history.replaceState(null,'','#intro-train');document.title=TITLES.train+'｜中文句式小遊戲';app.innerHTML=`<main class="intro-page">${header(TITLES.train,{extra:summaryButton('train'),levelType:'train'})}<section class="intro-layout"><div class="intro-large"><img src="assets/train-station-v1.png" alt="噴蒸氣的小島火車"></div><div class="intro-copy"><h2>把句子送上小火車！</h2><div class="train-tier-guide">${trainDifficulty(true,'1–3 關')}${trainDifficulty(false,'4–5 關')}</div><div class="visual-steps"><div>${trainTilePicture(TRAIN_LEVELS[0].firstTile,TRAIN_LEVELS[0].first)}<b>看圖</b></div><span>→</span><div class="action-demo">${icon('hand')}<b>拖字卡</b></div><span>→</span><div>${icon('check')}<b>開車</b></div></div><p>逗號、句號，也要上車。</p><button class="primary train-primary" data-action="start-train">${icon('play')}開始組句</button></div></section></main>`;}
function start(type){dispose();game=newGame(type);view=type;app.className='playing';lastFrame=performance.now();history.replaceState(null,'','#'+type);document.title=TITLES[type]+'｜中文句式小遊戲';if(type==='sushi')renderSushi();else if(type==='fishing')renderFishing();else if(type==='train')renderTrain();else{renderIsland();readIslandQuestion();}}
function renderSushi(){app.innerHTML=`<main class="game-page sushi-page">${header(TITLES.sushi,{playing:true,extra:`<div class="money" aria-label="所賺金錢">${icon('coin')}<span>收入</span><strong id="money">$${game.money}</strong></div>`})}<div class="play-area sushi-world"><div class="restaurant-art"></div><div class="order-status"><span id="order-number">訂單 1／${SUSHI.length}</span><div id="sushi-levels">${levelNavigation('sushi')}</div></div><div id="customer" class="customer-slot">${sprite('customer')}</div><section id="sushi-request" class="sushi-request"></section><div class="counter"></div><div id="ingredients" class="ingredients"></div><div id="sushi-feedback" class="feedback sushi-feedback" aria-live="polite"></div><div id="sushi-next" class="sushi-next"></div><div id="payment" class="payment-layer" aria-hidden="true"></div></div></main>`;enterCustomer();}
function enterCustomer(){const g=game,q=SUSHI[g.round];if(!q){finish('sushi');return;}g.phase='walking';g.locked=true;g.selected=null;g.speechFinished=false;g.animationFinished=false;g.advanceScheduled=false;$('#customer').className='customer-slot walking-in';$('#customer').innerHTML=sprite('customer',0,g.round%2);$('#sushi-request').innerHTML='';$('#ingredients').innerHTML='';$('#sushi-feedback').innerHTML='';$('#sushi-next').innerHTML='';$('#sushi-levels').innerHTML=levelNavigation('sushi');$('#order-number').textContent=`訂單 ${g.round+1}／${SUSHI.length}`;later(1150,()=>{g.phase='answering';g.locked=false;$('#customer').className='customer-slot';$('#sushi-request').innerHTML=`<div class="request-story">${vocabPicture(q.first)}<span aria-hidden="true">→</span>${vocabPicture(q.answer)}</div><div class="sentence">${textSentence(`我一${WORDS[q.first].text}，就`)}<span class="answer-gap">？</span><span class="punct">。</span></div>`;const opts=rotate(q.options,g.round);$('#ingredients').innerHTML=opts.map((id,i)=>`<button class="ingredient" data-sushi="${id}" aria-label="選擇${WORDS[id].text}"><span class="sushi-plate plate-${i}" aria-hidden="true"></span><span class="dish-wordcard"><span class="dish-wordtext"><strong class="${WORDS[id].text.length>=4?'long-word':''}">${WORDS[id].text}</strong><small class="jp">${WORDS[id].jp}</small></span>${vocabPicture(id,'dish-meaning')}</span></button>`).join('');audio('v2-q-'+q.first);});}
function advanceSushi(){const g=game;if(!g||g.type!=='sushi'||!g.speechFinished||!g.animationFinished||g.advanceScheduled)return;g.advanceScheduled=true;later(0,()=>{g.round++;enterCustomer();});}
function answerSushi(id,button){
 const g=game;if(g.locked)return;const q=SUSHI[g.round];
 if(id!==q.answer){
  sayWord(id,()=>later(0,()=>audio('v2-retry')));
  button.classList.add('try-card','wrong-answer');
  if(!button.querySelector('.wrong-badge'))button.insertAdjacentHTML('beforeend',`<span class="wrong-badge">${icon('cross')}再試一試！</span>`);
  $('#sushi-feedback').innerHTML='';later(550,()=>button.classList.remove('try-card'));return;
 }
 g.locked=true;g.phase='serving';button.classList.add('correct-card');for(const b of document.querySelectorAll('[data-sushi]'))b.disabled=true;
 $('#sushi-request .sentence').innerHTML=textSentence(sentence(q.first,id));$('#sushi-feedback').innerHTML='';button.insertAdjacentHTML('beforeend',`<span class="correct-badge">${icon('check')}答對了！</span>`);
 sayWord(id,()=>later(0,()=>audio('v2-s-'+q.first,()=>later(0,()=>{g.speechFinished=true;advanceSushi();}))));
 later(1500,()=>{if(payOrder(g,q.id)){$('#money').textContent='$'+g.money;$('#payment').innerHTML=`<span class="flying-coin">${icon('coin')}<b>+$${RULES.orderPrice}</b></span>`;}g.phase='paying';});
 later(3000,()=>{$('#customer').className='customer-slot walking-out';});
 later(4050,()=>{g.animationFinished=true;$('#payment').innerHTML='';advanceSushi();});
}
function rotate(a,n){const p=n%a.length;return [...a.slice(p),...a.slice(0,p)];}
function oceanMarkup(){return `<section class="ocean-arena" aria-label="兩位漁夫和游動魚群"><div class="sky-strip"></div><div class="pier"></div><div id="fisher-0" class="fisher-slot fisher-left">${sprite('fisher',0,0)}</div><div id="fisher-1" class="fisher-slot fisher-right">${sprite('fisher',0,1)}</div><div class="line line-left"></div><div class="line line-right"></div><div class="water-rim"></div>${Array.from({length:6},(_,i)=>`<span class="swim-lane" style="--level:${58+i%3*12}%;--speed:${14+i*2}s;--offset:${-i*4}s;--direction:${i%2?'reverse':'normal'}"><img src="assets/fish-${i%2?'blue':'gold'}-v2.png" alt="" style="--face:${i%2?-1:1}"></span>`).join('')}<div id="catch-layer" class="catch-layer"></div><div class="score-label score-left"><span>同學 1</span><strong id="score-0">0</strong></div><div class="score-label score-right"><span>同學 2</span><strong id="score-1">0</strong></div><div class="score-track"><span id="score-track-left"></span><span id="score-track-right"></span></div></section>`;}
function renderFishing(){app.innerHTML=`<main class="game-page fishing-page">${header(TITLES.fishing,{playing:true})}<div class="play-area fishing-play"><div class="fishing-nav-row">${levelNavigation('fishing')}</div>${oceanMarkup()}<div class="players">${[0,1].map(i=>`<section class="player player-${i}" id="player-${i}" aria-label="${i?'右':'左'}邊玩家"><div class="player-heading"><h2>同學 ${i+1}</h2><div class="streak" id="streak-${i}"></div></div><div class="player-upper" id="upper-${i}"></div><div class="choice-heading" id="choice-heading-${i}"></div><div class="three-choices" id="choices-${i}"></div><div class="feedback" id="feedback-${i}" aria-live="polite"></div></section>`).join('')}</div></div></main>`;renderPlayer(0);renderPlayer(1);}
function fishPrompt(p){const first=p.first?WORDS[p.first].text:'［？］',result=p.result?WORDS[p.result].text:'［？］';return textSentence(`我一${first}，就${result}。`);}
function linkedSentence(p){
 const feedback=p.feedback,kind=feedback?.correct?'correct':feedback?'rethink':'';
 const photo=(id,second)=>id?`<span class="linked-photo ${second&&feedback&&!feedback.correct?'photo-rethink':''}">${vocabPicture(id)}${second&&feedback?`<span class="photo-status ${feedback.correct?'good-photo':'bad-photo'}">${icon(feedback.correct?'check':'cross')}</span>`:''}</span>`:'<span class="linked-blank">？</span>';
 return `<div class="linked-sentence ${kind}"><div class="linked-half">${photo(p.first,false)}<span class="word-image-arrow" aria-hidden="true">↑</span><div class="linked-words">${textSentence('我一'+(p.first?WORDS[p.first].text:'［？］')+'，')}</div></div><div class="linked-half">${photo(p.result,true)}<span class="word-image-arrow amber-arrow" aria-hidden="true">↑</span><div class="linked-words">${textSentence('就'+(p.result?WORDS[p.result].text:'［？］')+'。')}</div></div></div>`;
}
function renderPlayer(i){const p=game.players[i],left=remainingFirsts(p),allDone=left.length===0&&p.stage==='first';
 $('#upper-'+i).innerHTML=allDone?`<div class="player-finished">${icon('check')}<b>完成八句！</b><p>釣到 ${p.fish} 條魚。</p></div>`:linkedSentence(p);
 $('#streak-'+i).innerHTML=`<span>連對 ${p.streak}</span><span class="streak-stars">${Array.from({length:5},(_,n)=>`<i class="${n<(p.streak?(p.streak%5||5):0)?'lit':''}">${icon('star')}</i>`).join('')}</span>`;
 $('#choice-heading-'+i).innerHTML=allDone?'':`<b>${p.stage==='first'?'選前一件事':'選緊接的事情'}</b>${p.stage==='result'&&!p.locked?`<button class="back-choice" data-back="${i}" aria-label="重新選前一件事">${icon('back')}換前項</button>`:''}`;
 const options=p.stage==='first'?left.slice(0,3):answerOptions(p.first);
 $('#choices-'+i).innerHTML=allDone?'':rotate(options,i+p.done.size).map(id=>wordChoice(id,`data-player="${i}" data-word="${id}" ${p.locked?'disabled':''}`,p.result===id?(p.feedback?.correct?'correct-card':p.feedback?.grade==='weak'?'weak-card':'wrong-card'):'')).join('');
 $('.fishing-nav-row').innerHTML=levelNavigation('fishing');
 const v=p.feedback;$('#feedback-'+i).innerHTML=v?`<div class="${v.correct?'success-note':'visual-retry '+(v.grade==='weak'?'gentle-note':'try-note')}">${icon(v.correct?'check':'cross')}<span>${v.correct?'合理！':'再試一試！'}</span>${!v.correct?`<span class="retry-hand">${icon('hand')}</span>`:''}</div>`:'';
}
function selectFishing(i,id){const g=game,p=g.players[i];if(p.locked)return;if(p.stage==='first'){if(chooseFirst(p,id))renderPlayer(i);return;}const verdict=scoreResponse(p,id);if(!verdict)return;renderPlayer(i);if(verdict.correct){catchFish(i,verdict.big,verdict.replay);updateScores();later(3100,()=>{nextPlayerRound(p);renderPlayer(i);if(g.players.every(v=>remainingFirsts(v).length===0))finish('fishing');});}else{audio('v2-retry');announce(verdict.reason);}}
function catchFish(i,big,replay=false){const f=$('#fisher-'+i);f.classList.add('reeling');const el=document.createElement('div');el.className=`caught-fish caught-${i} ${big?'big-fish':''}`;el.innerHTML=`<img src="assets/fish-${big?'blue':'gold'}-v2.png" alt="${big?'大魚上鉤':'小魚上鉤'}"><b>${replay?'答對了！':big?'大魚！＋5':'答對！＋1'}</b>`;$('#catch-layer').append(el);later(850,()=>{f.classList.remove('reeling');f.classList.add('happy');});later(2850,()=>{el.remove();f.classList.remove('happy');});announce(`${i?'右':'左'}邊同學釣到${big?'大':'小'}魚！`);}
function updateScores(){const [a,b]=game.players;$('#score-0').textContent=a.score;$('#score-1').textContent=b.score;const pct=(a.score+1)/(a.score+b.score+2)*100;$('#score-track-left').style.width=pct+'%';$('#score-track-right').style.width=(100-pct)+'%';}
function renderIsland(){
 const g=game,q=LEVELS[g.round],done=g.phase==='complete',acting=g.phase==='acting',active=acting||done;
 app.innerHTML=`<main class="game-page island-page">${header(TITLES.island,{playing:true})}<div class="play-area island-play"><div class="island-progress"><strong>${q.category}・第 ${g.round+1} 關</strong>${levelNavigation('island')}</div><section class="island-main"><div class="island-scene" id="island-scene">${paintedScene(q.kind,{active,settled:done,label:active?q.sentence:q.action+'的情境圖'})}</div><div class="island-prompt"><div class="sentence">${islandSentence(active?q.sentence:q.before)}${active?'':'<span class="answer-gap">？</span><span class="punct">。</span>'}</div><div class="island-feedback" aria-live="polite">${done?`<span class="success-note">${icon('check')}答對了！</span>`:acting?`<span class="success-note">${icon('check')}馬上發生了！</span>`:g.phase==='selected'?`<span class="success-note">${icon('check')}按左下的動作！${icon('hand')}</span>`:g.phase==='retry'?`<span class="try-note visual-retry">${icon('cross')}再試一試！<span class="retry-hand">${icon('hand')}</span></span>`:'<span>先選結果，再做動作。</span>'}</div></div></section><section class="island-controls"><div class="action-station"><span class="role-label">同學 ${g.round%2+1}：做動作</span><button class="action-button primary blue ${g.phase==='selected'?'ready-action':''}" data-action="island-act" aria-label="${q.action}" ${g.phase==='selected'?'':'disabled'}>${islandWordPicture(q.actionTile,q.action)}<span>${q.action}</span>${icon('hand')}</button></div><div class="result-station"><span class="role-label">同學 ${g.round%2?1:2}：選結果</span><div class="island-options">${rotate(q.options,g.round).map(o=>{const chosen=g.selected===o.id;return `<button class="word-choice island-choice ${chosen?(g.selected===q.correct?'correct-card':'wrong-card'):''}" data-island="${o.id}" ${active?'disabled':''} aria-label="${o.text}">${islandWordPicture(o.tile,o.text)}<strong>${o.text}</strong><small class="jp">${o.jp}</small>${chosen?`<span class="choice-status ${g.selected===q.correct?'status-correct':'status-wrong'}">${icon(g.selected===q.correct?'check':'cross')}</span>`:''}</button>`;}).join('')}</div></div></section></div></main>`;
}
function islandAnswer(id){const ok=chooseIsland(game,id);renderIsland();if(!ok){audio('v2-retry');announce('再試一試。');}}
function readIslandQuestion(){const q=LEVELS[game.round];audio('v3-island-q-'+q.id);}
function islandAct(){const g=game,q=LEVELS[g.round];if(!performIsland(g))return;clearAudio();renderIsland();later(3000,()=>{completeIsland(g);renderIsland();audio('v2-island-'+q.id,()=>later(350,()=>{if(g.round===LEVELS.length-1)finish('island');else if(nextIsland(g)){renderIsland();readIslandQuestion();}}));announce(q.sentence);});}
function finish(type){cancelTrainDrags();finishGame(game);clearAudio();app.className='playing';view=type;history.replaceState(null,'','#'+type);renderReview(type);}
function renderReview(type){
 const entries=reviewEntries(game).map(q=>({...q,pics:q.pictures.map(p=>p.word?vocabPicture(p.word):p.train!==undefined?trainTilePicture(p.train):islandWordPicture(p.island)).join('<span class="review-arrow" aria-hidden="true">→</span>')}));
 const extra=type==='sushi'?`<div class="money"><span>收入</span><strong>$${game.money}</strong></div>`:'';
 app.innerHTML=`<main class="game-page review-game review-${type}">${header(TITLES[type]+'・句子重溫',{playing:true,extra,levelType:type})}<section class="play-area review-page">${type==='fishing'?`<div class="review-result">${game.players.map((p,i)=>`<span>${icon('fish')}同學 ${i+1}：${p.score} 分</span>`).join('')}</div>`:''}<h2>看圖，讀一讀完整句子。</h2><div class="review-grid">${entries.map(q=>`<article class="review-card"><div class="review-pictures">${q.pics}</div><p class="sentence">${textSentence(q.text)}</p><button class="review-audio control" data-review="${q.audio}" aria-label="播放：${q.text}">${icon('sound')}<span>聽</span></button></article>`).join('')}</div></section></main>`;
}
function trainWordPicture(id,cls=''){
 const t=TRAIN_TOKENS[id];if(!t)return '';
 return Number.isInteger(t.tile)?trainTilePicture(t.tile,t.text,cls):'';
}
function trainTilePicture(tile,label='詞語圖畫',cls=''){const x=tile%4*362+3,y=Math.floor(tile/4)*362+3,clip='train-pic-'+(++pictureSerial);return `<svg class="train-word-picture ${cls}" viewBox="${x} ${y} 356 356" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${esc(label)}"><defs><clipPath id="${clip}"><rect x="${x}" y="${y}" width="356" height="356"/></clipPath></defs><image href="assets/train-words-v3.png" width="1448" height="1086" clip-path="url(#${clip})"/></svg>`;}
function trainEngine(active=false){const clip='engine-'+(++pictureSerial);return `<svg class="train-engine ${active?'running-engine':''}" viewBox="0 0 1024 768" preserveAspectRatio="xMidYMid meet" role="img" aria-label="噴蒸氣的小火車"><defs><clipPath id="${clip}"><rect width="1024" height="768"/></clipPath></defs><g clip-path="url(#${clip})"><image class="frame16-atlas" href="assets/train-engine-16-v1.png" width="4096" height="3072"/></g></svg>`;}
function trainCarArt(active=false){return `<svg class="painted-train-car ${active?'car-animation-active':''}" viewBox="0 0 258 270" preserveAspectRatio="xMidYMax meet" role="img" aria-label="彩繪火車車廂">${TRAIN_CARRIAGE_ART.frames.map((f,i)=>{const [x,y,r,b]=f.bounds,w=r-x,h=b-y;return `<svg class="car-frame car-frame-${i}" x="${(258-w)/2}" y="${270-h}" width="${w}" height="${h}" viewBox="${x} ${y} ${w} ${h}" overflow="hidden"><image href="assets/train-carriages-16-v3.png" width="${TRAIN_CARRIAGE_ART.width}" height="${TRAIN_CARRIAGE_ART.height}"/></svg>`;}).join('')}</svg>`;}
function trainCarriages(){const q=TRAIN_LEVELS[game.round],v=game.trainFeedback;return q.tokens.map((expected,i)=>{const id=game.trainSlots[i],t=TRAIN_TOKENS[id],letters=q.showLengthHints?TRAIN_TOKENS[expected].text.length:4,wrong=v&&!v.correct&&v.wrong.includes(i);return `<button class="train-car painted-car ${q.showLengthHints?'hint-car':'equal-car'} ${id?'is-filled':''} ${wrong?'wrong-car':''} ${id&&game.trainSelected===id?'selected-token':''} ${[...trainDrags.values()].some(d=>d.id===id)?'is-dragging':''}" data-train-slot="${i}" ${id?`data-train-token="${id}"`:''} style="--letters:${letters};--word-length:${t?.text.length||1}" aria-label="第 ${i+1} 節車廂${id?'：'+t.text:'，空位'}" ${game.phase!=='assembling'?'disabled':''}>${trainCarArt(game.phase==='departing')}<span class="car-body">${id?`<strong class="placed-word ${t.carriageLines?'wrapped-train-word':''} ${t.jp?'':'punct'}">${t.carriageLines?t.carriageLines.map(line=>`<span>${line}</span>`).join(''):t.text}</strong>`:'<span class="car-gap" aria-hidden="true"></span>'}${wrong?`<span class="car-error">${icon('cross')}</span>`:''}</span></button>`;}).join('');}
function trainBank(){const q=TRAIN_LEVELS[game.round],order=q.tokens.length===8?[5,2,0,6,4,7,1,3]:[5,2,0,4,6,1,3];return rotate(order,game.round).map(i=>{const id=q.tokens[i],t=TRAIN_TOKENS[id],placed=game.trainSlots.includes(id),held=[...trainDrags.values()].some(d=>d.id===id);return `<button class="word-choice train-word-card ${t.tile===null?'train-text-card':''} ${placed?'used-token':''} ${held?'is-dragging':''} ${id&&game.trainSelected===id?'selected-token':''}" data-train-token="${id}" aria-label="詞卡：${t.voiceLabel}" ${placed||game.phase!=='assembling'?'disabled':''}>${trainWordPicture(id)}<strong class="${t.jp?'':'punct'}">${t.text}</strong>${t.jp?`<small class="jp">${t.jp}</small>`:''}</button>`;}).join('');}
function renderTrain(){const q=TRAIN_LEVELS[game.round],moving=game.phase==='departing';app.innerHTML=`<main class="game-page train-page">${header(TITLES.train,{playing:true})}<div class="play-area train-play"><div class="island-progress">${trainDifficulty(q.showLengthHints,'第 '+(game.round+1)+' 關')}${levelNavigation('train')}</div><section class="train-question"><div class="train-story">${trainTilePicture(q.firstTile,q.first)}<span class="story-arrow" aria-hidden="true">→</span>${trainTilePicture(q.resultTile,q.result)}</div><div class="train-question-copy">${moving?`<p class="sentence">${textSentence(q.sentence)}</p><span class="success-note">${icon('check')}答對了！</span>`:`<p>${icon('hand')} 把詞卡拖上車廂。</p><div class="train-progress-pictures" aria-hidden="true"><b class="first-connector">一</b>${icon('arrow')}<b class="then-connector">就</b></div>`}</div></section><section class="train-track" aria-label="排列句子的火車"><div class="track-line"></div><div class="train-rake ${moving?'train-departing':''}" id="train-rake"><div class="train-carriages ${q.tokens.length>7?'long-train':''}" id="train-carriages">${trainCarriages()}</div><div class="engine-position">${trainEngine(moving)}</div></div></section><div class="train-feedback" id="train-feedback" aria-live="polite">${game.trainFeedback&&!game.trainFeedback.correct?`<span class="try-note">${icon('cross')}再試一試！</span>`:''}</div><section class="train-bank" id="train-bank" style="--train-columns:${q.tokens.length}" aria-label="可拖動的詞卡">${trainBank()}</section></div></main>`;}
function updateTrainBoard(){if(game?.type!=='train'||!$('#train-bank'))return;$('#train-carriages').innerHTML=trainCarriages();$('#train-bank').innerHTML=trainBank();$('#train-feedback').innerHTML=game.trainFeedback&&!game.trainFeedback.correct?`<span class="try-note">${icon('cross')}再試一試！</span>`:'';}
function checkTrain(){const g=game;if(!g||g.type!=='train'||g.phase!=='assembling'||trainDrags.size)return;const v=trainVerdict(g);if(!v.complete)return;g.trainFeedback=v;if(!v.correct){updateTrainBoard();audio('v2-retry');return;}if(!departTrain(g))return;g.trainSpeechFinished=false;g.trainAnimationFinished=false;g.advanceScheduled=false;renderTrain();audio(TRAIN_LEVELS[g.round].audio,()=>later(0,()=>{g.trainSpeechFinished=true;advanceTrain();}));later(2850,()=>{g.trainAnimationFinished=true;advanceTrain();});}
function advanceTrain(){const g=game;if(!g||g.type!=='train'||!g.trainSpeechFinished||!g.trainAnimationFinished||g.advanceScheduled)return;g.advanceScheduled=true;later(350,()=>{if(g.round===TRAIN_LEVELS.length-1)finish('train');else jumpToLevel(g.round+1,'train');});}
function cancelTrainDrags(){for(const [pointer,d]of trainDrags){d.ghost?.remove();trainDrags.delete(pointer);if(app.hasPointerCapture?.(pointer))app.releasePointerCapture(pointer);}document.querySelectorAll('.drop-target,.is-dragging').forEach(e=>e.classList.remove('drop-target','is-dragging'));}
function drawDragTargets(){document.querySelectorAll('.drop-target').forEach(e=>e.classList.remove('drop-target'));for(const d of trainDrags.values())if(d.slot!==null)document.querySelector(`[data-train-slot="${d.slot}"]`)?.classList.add('drop-target');}
app.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-train-token]'),g=game;if(!b||b.disabled||!g||g.type!=='train'||g.paused||g.phase!=='assembling'||[...trainDrags.values()].some(d=>d.id===b.dataset.trainToken))return;e.preventDefault();const rect=b.getBoundingClientRect(),ghost=b.cloneNode(true);ghost.removeAttribute('id');ghost.classList.add('drag-ghost');Object.assign(ghost.style,{width:rect.width+'px',height:rect.height+'px',left:e.clientX-rect.width/2+'px',top:e.clientY-rect.height/2+'px'});document.body.append(ghost);trainDrags.set(e.pointerId,{id:b.dataset.trainToken,game:g,ghost,width:rect.width,height:rect.height,slot:null});b.classList.add('is-dragging');app.setPointerCapture(e.pointerId);audio(TRAIN_TOKENS[b.dataset.trainToken].audio);});
app.addEventListener('pointermove',e=>{const d=trainDrags.get(e.pointerId);if(!d)return;e.preventDefault();d.ghost.style.left=e.clientX-d.width/2+'px';d.ghost.style.top=e.clientY-d.height/2+'px';const slot=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-train-slot]');d.slot=slot?Number(slot.dataset.trainSlot):null;drawDragTargets();});
function endTrainDrag(e,cancelled=false){const d=trainDrags.get(e.pointerId);if(!d)return;trainDrags.delete(e.pointerId);d.ghost.remove();if(app.hasPointerCapture(e.pointerId))app.releasePointerCapture(e.pointerId);if(!cancelled&&game===d.game&&!game.paused){const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-train-slot]');if(target){const index=Number(target.dataset.trainSlot),occupied=game.trainSlots[index],held=[...trainDrags.values()].some(other=>other.id===occupied);if(!held)placeTrainToken(game,d.id,index);}else removeTrainToken(game,d.id);}updateTrainBoard();drawDragTargets();if(!cancelled)checkTrain();}
app.addEventListener('pointerup',e=>endTrainDrag(e));app.addEventListener('pointercancel',e=>endTrainDrag(e,true));app.addEventListener('lostpointercapture',e=>endTrainDrag(e,true));app.addEventListener('dragstart',e=>{if(e.target.closest('[data-train-token]'))e.preventDefault();});
app.addEventListener('keydown',e=>{if(game?.type!=='train'||game.paused||game.phase!=='assembling'||!['Enter',' '].includes(e.key))return;const b=e.target.closest('[data-train-token],[data-train-slot]');if(!b||b.disabled)return;e.preventDefault();if(b.dataset.trainSlot!==undefined&&game.trainSelected){placeTrainToken(game,game.trainSelected,Number(b.dataset.trainSlot));game.trainSelected=null;updateTrainBoard();checkTrain();}else if(b.dataset.trainToken){game.trainSelected=b.dataset.trainToken;audio(TRAIN_TOKENS[game.trainSelected].audio);updateTrainBoard();}});

app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const a=b.dataset.action;
 if(a==='home'){home();return;}if(a==='pause'){pause();return;}if(a==='restart'){if(game)start(game.type);return;}
 if(a==='summary'){const type=game?.type||b.dataset.type;if(TITLES[type]){if(!game)game=newGame(type);finish(type);}return;}
 if(b.dataset.jumpLevel!==undefined){jumpToLevel(Number(b.dataset.jumpLevel),b.dataset.jumpGame);return;}
 if(game?.paused)return;
 if(a?.startsWith('intro-')){intro(a.slice(6));return;}if(a?.startsWith('start-')){start(a.slice(6));return;}

 if(b.dataset.review&&game){audio(b.dataset.review);return;}
 if(a==='island-act'){islandAct();return;}
 if(b.dataset.sushi&&game?.type==='sushi')answerSushi(b.dataset.sushi,b);
 if(b.dataset.word&&game?.type==='fishing')selectFishing(Number(b.dataset.player),b.dataset.word);
 if(b.dataset.back!==undefined&&game?.type==='fishing'){const i=Number(b.dataset.back),p=game.players[i];if(!p.locked){p.first=null;p.result=null;p.stage='first';p.feedback=null;renderPlayer(i);}}
 if(b.dataset.island&&game?.type==='island')islandAnswer(b.dataset.island);
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&game)pause();});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&game&&!game.paused)pause();});
window.addEventListener('popstate',()=>home());
function frame(now){const delta=Math.max(0,now-lastFrame);lastFrame=now;if(game&&!game.paused)game.queue.tick(delta);requestAnimationFrame(frame);}requestAnimationFrame(frame);
const route=location.hash.slice(1);if(['sushi','fishing','island','train'].includes(route))intro(route);else if(route.startsWith('intro-')&&TITLES[route.slice(6)])intro(route.slice(6));else home();
